    public func auditAs(_ reason: String) -> CustomerOrderAudited {
        teaqlEntityRoot.setLocalAuditReason(teaqlEntityKey, reason: reason)
        return CustomerOrderAudited(entity: self, reason: reason)
    }

    @discardableResult
    public mutating func markForDeletion() -> Self {
        teaqlEntityRoot.markAsDeleted(teaqlEntityKey)
        return self
    }
}

public struct CustomerOrderAudited: Sendable {
    public let entity: CustomerOrder
    public let reason: String

    public func save(_ context: UserContext) async throws -> CustomerOrder {
        _ = try MutationIntent(comment: reason)
        if try entity.teaqlIsCancelledNew() { throw TeaQLError.execution("Cannot save a cancelled new root") }
        try teaqlValidateLoadedIdentities()
        // Freeze an invocation-owned value graph before reviewing it. Attach
        // reached pending children in the value copy, not just in loop locals,
        // so execution cannot re-import stale source-ledger values after Fix.
        var owned = entity
        let ledger = owned.teaqlEntityRoot
        try owned.teaqlAttachRoot(ledger)
        try CustomerOrderAudited(entity: owned, reason: reason).teaqlNormalizeGraph()
        try owned.teaqlAttachRoot(ledger)
        return try await CustomerOrderAudited(entity: owned, reason: reason).teaqlSaveOwnedGraph(context)
    }

    private func teaqlSaveOwnedGraph(_ context: UserContext) async throws -> CustomerOrder {
        try teaqlValidateLoadedIdentities()
        try teaqlNormalizeGraph()
        guard try teaqlValidateInputGraph() else { return entity }
        return try await context.executeGraphSave(comment: reason, rootEntityType: "CustomerOrder", preparing: { context, session in
            try teaqlValidateLoadedIdentities()
            try teaqlNormalizeGraph()
            _ = try teaqlValidateInputGraph()
            try teaqlPreflightGraph(context, session: session)
            // A later Fix can add an intent to an already visited owner.
            // Re-admit the entire graph before customer policy or provider I/O.
            try teaqlNormalizeGraph()
            _ = try teaqlValidateInputGraph()
        }) { context, session in
            _ = try await teaqlSavePreflighted(context, session: session,
                scope: session.scope(key: entity.teaqlEntityKey))
            return try entity.teaqlRebuildSavedGraph(session.readback())
        }
    }

    /// Executes a node whose complete aggregate graph was already preflighted
    /// by the public save entry point. Generated cascade code must use this
    /// path so policy review remains a strict preflight-then-mutate sequence.
    func teaqlSavePreflighted(_ context: UserContext, session: GraphMutationSession,
                            scope: TraceScopeToken) async throws -> CustomerOrder {
        guard try session.visitEntity(entity, phase: .write) else {
            return try entity.teaqlRebuildSavedGraph(session.readback())
        }
        if try entity.teaqlIsCancelledNew() { return entity }
        let saved = try await AuditedEntity(entity: entity, reason: reason)
            .saveInGraph(context, session: session, scope: scope)
        let activeScope = try scope.assigning(entity.teaqlEntityKey,
            to: EntityKey(entity: "CustomerOrder", id: .int(saved.id)))
        for (index, var child) in entity.orderItemList.enumerated() {
            if try child.teaqlIsCancelledNew() { continue }
            try child.teaqlAttachRoot(entity.teaqlEntityRoot)
            // The runtime resolves declared temporary references in its private
            // outgoing mutation. Never change a reviewed caller ledger here.
            let localReason = child.teaqlEntityRoot.localAuditReason(child.teaqlEntityKey)
            let childScope = try session.scope(key: child.teaqlEntityKey,
                localReason: localReason, parent: activeScope)
            do {
                _ = try await OrderItemAudited(entity: child, reason: localReason ?? reason)
                    .teaqlSavePreflighted(context, session: session, scope: childScope)
            }
            catch let error as CheckException {
                let prefix = ObjectLocation.property("order_item_list").index(index)
                throw CheckException(context.translateCheckResults(error.violations.map { violation in
                    violation.prefixed(by: prefix)
                }))
            }
        }
        for (index, var child) in entity.paymentList.enumerated() {
            if try child.teaqlIsCancelledNew() { continue }
            try child.teaqlAttachRoot(entity.teaqlEntityRoot)
            // The runtime resolves declared temporary references in its private
            // outgoing mutation. Never change a reviewed caller ledger here.
            let localReason = child.teaqlEntityRoot.localAuditReason(child.teaqlEntityKey)
            let childScope = try session.scope(key: child.teaqlEntityKey,
                localReason: localReason, parent: activeScope)
            do {
                _ = try await PaymentAudited(entity: child, reason: localReason ?? reason)
                    .teaqlSavePreflighted(context, session: session, scope: childScope)
            }
            catch let error as CheckException {
                let prefix = ObjectLocation.property("payment_list").index(index)
                throw CheckException(context.translateCheckResults(error.violations.map { violation in
                    violation.prefixed(by: prefix)
                }))
            }
        }
        for (index, var child) in entity.shipmentList.enumerated() {
            if try child.teaqlIsCancelledNew() { continue }
            try child.teaqlAttachRoot(entity.teaqlEntityRoot)
            // The runtime resolves declared temporary references in its private
            // outgoing mutation. Never change a reviewed caller ledger here.
            let localReason = child.teaqlEntityRoot.localAuditReason(child.teaqlEntityKey)
            let childScope = try session.scope(key: child.teaqlEntityKey,
                localReason: localReason, parent: activeScope)
            do {
                _ = try await ShipmentAudited(entity: child, reason: localReason ?? reason)
                    .teaqlSavePreflighted(context, session: session, scope: childScope)
            }
            catch let error as CheckException {
                let prefix = ObjectLocation.property("shipment_list").index(index)
                throw CheckException(context.translateCheckResults(error.violations.map { violation in
                    violation.prefixed(by: prefix)
                }))
            }
        }
        return saved
    }

    /// Check all original identities without attaching ledgers or changing FKs.
    func teaqlValidateLoadedIdentities() throws {
        if try entity.teaqlIsCancelledNew() { return }
        try AuditedEntity(entity: entity, reason: reason).validateLoadedIdentity()
        for child in entity.orderItemList {
            try OrderItemAudited(entity: child, reason: reason).teaqlValidateLoadedIdentities()
        }
        for child in entity.paymentList {
            try PaymentAudited(entity: child, reason: reason).teaqlValidateLoadedIdentities()
        }
        for child in entity.shipmentList {
            try ShipmentAudited(entity: child, reason: reason).teaqlValidateLoadedIdentities()
        }
