    func teaqlNormalizeGraph() throws {
        if try entity.teaqlIsCancelledNew() { return }
        LoadedScalarRestoration.discardRestoredFields(of: entity)
        for var child in entity.orderItemList {
            if try child.teaqlIsCancelledNew() { continue }
            try child.teaqlAttachRoot(entity.teaqlEntityRoot)
            if child.customerOrder != entity.teaqlPreflightID {
                child.updateCustomerOrder(entity.teaqlPreflightID)
            }
            let childReason = child.teaqlEntityRoot.localAuditReason(child.teaqlEntityKey) ?? reason
            try OrderItemAudited(entity: child, reason: childReason).teaqlNormalizeGraph()
        }
        for var child in entity.paymentList {
            if try child.teaqlIsCancelledNew() { continue }
            try child.teaqlAttachRoot(entity.teaqlEntityRoot)
            if child.customerOrder != entity.teaqlPreflightID {
